<div class="modal fade" id="editTaskModal" tabindex="-1"><div class="modal-dialog modal-xl modal-dialog-centered modal-dialog-scrollable"><div class="modal-content border-0"><div class="modal-header"><h5 class="modal-title">Chỉnh sửa công việc</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><form method="POST" action="{{route('tasks.update',$task)}}" class="row g-3">@csrf @method('PUT')<div class="col-md-8"><label class="form-label">Tên công việc</label><input class="form-control" name="title" value="{{old('title',$task->title)}}" maxlength="180" required></div><div class="col-md-4"><label class="form-label">Hạn hoàn thành</label><input class="form-control" type="datetime-local" name="due_at" value="{{old('due_at',$task->due_at->format('Y-m-d\TH:i'))}}" required></div><div class="col-md-8"><label class="form-label">Nội dung / ghi chú</label><textarea class="form-control" name="description" rows="3" maxlength="5000">{{old('description',$task->description)}}</textarea></div><div class="col-md-4"><label class="form-label">Ưu tiên</label><select class="form-select" name="priority"><option value="normal" @selected(old('priority',$task->priority)==='normal')>Bình thường</option><option value="high" @selected(old('priority',$task->priority)==='high')>Quan trọng</option><option value="low" @selected(old('priority',$task->priority)==='low')>Thấp</option></select></div><div class="col-lg-8"><label class="form-label">Người nhận (chọn nhiều)</label><div class="border rounded-3 p-3" style="max-height:260px;overflow:auto">@php($selectedIds=collect(old('assignee_ids',$task->assignees->pluck('user_id')->all()))->map(fn($id)=>(int)$id)->all()) @foreach($users as $user)<label class="d-flex gap-2 py-1"><input class="form-check-input" type="checkbox" name="assignee_ids[]" value="{{$user->id}}" data-edit-assignee-name="{{$user->name}}" @checked(in_array($user->id,$selectedIds,true))><span><strong>{{$user->name}}</strong> <small class="text-muted">{{$user->email}}</small></span></label>@endforeach</div></div><div class="col-lg-4"><label class="form-label">Người chủ trì</label><select class="form-select" name="lead_id" data-edit-task-lead data-selected-value="{{old('lead_id',$task->assignees->firstWhere('is_lead',true)?->user_id)}}" required><option value="">Chọn người nhận trước</option></select><small class="text-muted">Chỉ hiển thị người đã tích.</small></div><div class="col-12 text-end"><button class="btn btn-primary"><i class="bi bi-floppy me-1"></i>Lưu thay đổi</button></div></form></div></div></div></div>
@push('scripts')<script>document.addEventListener('DOMContentLoaded',()=>{const lead=document.querySelector('[data-edit-task-lead]'),items=[...document.querySelectorAll('[data-edit-assignee-name]')];if(lead){const refresh=()=>{const selected=lead.value||lead.dataset.selectedValue;lead.innerHTML='<option value="">Chọn người chủ trì</option>';items.filter(item=>item.checked).forEach(item=>lead.add(new Option(item.dataset.editAssigneeName,item.value,false,item.value===selected)));if(![...lead.options].some(option=>option.value===selected))lead.value=''};items.forEach(item=>item.addEventListener('change',refresh));refresh()}@if($errors->any())bootstrap.Modal.getOrCreateInstance(document.getElementById('editTaskModal')).show();@endif});</script>@endpush
